        /* Round model (v1.2.0, EQIL 2026-10-30). One quarter per round.
           Stocks carried in domainState: brand equity, awareness (upper-funnel reach that feeds search and
           affiliate demand), active customers (retention through owned media), content and SEO stock.
           Brand focus splits creative between conversion now and brand building later, both with
           diminishing returns. Market events: competitor bidding (R2+), attribution vendor (R3, a
           measurement event only), iOS ATT (R4+), creator controversy (R5). */
        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var Q = 600000;
            var clamp = this._clamp;
            if (ds.activeCustomers == null) ds.activeCustomers = ds.totalCustomers || 50000;
            if (ds.awareness == null) ds.awareness = 1;
            if (ds.creatorExposure == null) ds.creatorExposure = 0;
            if (!ds.scoreHistory) ds.scoreHistory = [];
            if (round >= 2) ds.competitorActive = true;
            if (round >= 4) ds.iosPrivacyActive = true;
            var comp = ds.competitorActive, ios = ds.iosPrivacyActive;
            var COMP = { sem: 0.82, affiliate: 0.85, social: 0.88, influencer: 0.92, content: 0.95, email: 1.0 };
            var a = { sem: d.semPct, social: d.socialPct, email: d.emailPct, content: d.contentPct, influencer: d.influencerPct, affiliate: d.affiliatePct };
            var bf = clamp(d.brandFocus / 100, 0, 1);
            var upper = (0.5 * a.social + 0.8 * a.content + a.influencer) / 100;
            ds.awareness = clamp(0.5 * ds.awareness + 0.5 * Math.sqrt(upper / 0.355), 0.3, 1.3);
            var brandMult = 1 + 0.35 * Math.tanh((ds.brandEquity - 40) / 25);
            var perfFocus = Math.pow(1 - bf, 0.3) / Math.pow(0.7, 0.3);
            ds.creatorExposure = (ds.creatorExposure * (round - 1) + a.influencer / 100) / round;
            var scandal = (round === 5 && ds.creatorExposure > 0.18);
            var paid = 0, brandMix = 0, self = this;
            ['sem', 'social', 'email', 'content', 'influencer', 'affiliate'].forEach(function(ch) {
                var pct = a[ch] / 100, spend = Q * pct, cfg = self.CHANNELS[ch];
                var eff = Math.max(0.2, cfg.baseEff * (1 - cfg.dimFactor * pct)) * brandMult * (comp ? COMP[ch] : 1);
                if (ch === 'sem' || ch === 'affiliate') eff *= 0.5 + 0.5 * ds.awareness;
                if (ios) {
                    if (ch === 'social') eff *= 0.65;
                    if (ch === 'sem') eff *= 0.92;
                    if (ch === 'affiliate') eff *= 0.95;
                    if (ch === 'email') eff *= 1.2;
                }
                if (ch === 'content') {
                    ds.cumulativeContentBonus += 0.038 * Math.sqrt(pct);
                    eff += ds.cumulativeContentBonus;
                }
                if (ch === 'influencer' && scandal) eff *= 0.6;
                paid += spend * eff * perfFocus * (cfg.perfWeight / 0.5) * 0.8;
                brandMix += pct * cfg.brandWeight;
            });
            var croBonus = round >= 2 ? 1 + (a.content + a.email) / 50 * 0.08 : 1;
            paid *= croBonus;
            var organic = 2500 * (1 + 0.8 * Math.tanh((ds.brandEquity - 40) / 30)) * Math.sqrt(ds.awareness) + 15000 * ds.cumulativeContentBonus;
            var newCust = paid / 45 + organic;
            var emailReach = 1 - Math.exp(-(a.email / 12) * (ios ? 1.2 : 1));
            var ret = clamp(0.425 + 0.30 * emailReach + 0.12 * (ds.brandEquity - 40) / 40, 0.35, 0.78);
            var ordersPerActive = 0.907 * (1 + 0.25 * Math.tanh((ds.brandEquity - 40) / 30));
            var existing = ds.activeCustomers * ordersPerActive * 45;
            ds.activeCustomers = Math.round(ds.activeCustomers * ret + newCust);
            ds.totalCustomers += Math.round(newCust);
            var decay = 0.15 * ds.brandEquity * (comp ? 1.15 : 1);
            ds.brandEquity = clamp(ds.brandEquity + 90 * brandMix * Math.sqrt(bf) * (1 - ds.brandEquity / 100) - decay, 5, 95);
            if (scandal) ds.brandEquity = clamp(ds.brandEquity - 60 * (ds.creatorExposure - 0.18), 5, 95);
            ds.brandEquity = Math.round(ds.brandEquity * 10) / 10;
            var total = paid + existing + organic * 45;
            ds.monthlyRevenue = Math.round(total / 3);
            ds.cac = Math.round(Q / Math.max(1, newCust) * 100) / 100;
            ds.conversionRate = Math.max(0.5, Math.round((2.1 + (ds.brandEquity - 40) * 0.015 + (croBonus - 1) * 5) * 100) / 100);
            ds.repeatPurchaseRate = Math.round(clamp(35 + (ret - 0.567) * 150, 10, 65) * 10) / 10;
            ds.clv = Math.round(45 * (1 + ds.repeatPurchaseRate * 0.111));
            var roas = Math.round(paid / Q * 100) / 100;
            ds.revenueHistory.push(ds.monthlyRevenue);
            ds.brandEquityHistory.push(ds.brandEquity);
            ds.cacHistory.push(ds.cac);
            ds.roasHistory.push(roas);
            ds.clvHistory.push(ds.clv);
            ds.convRateHistory.push(ds.conversionRate);
            var score = this._composite(ds);
            ds.scoreHistory.push(score);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: score, tier: this._tier(score) });
            ds.performanceTier = this._tier(score);
            return {
                period: round, quarterRevenue: Math.round(total), monthlyRevenue: ds.monthlyRevenue,
                brandEquity: ds.brandEquity, cac: ds.cac, roas: roas, conversionRate: ds.conversionRate,
                clv: ds.clv, newCustomers: Math.round(newCust), repeatRate: ds.repeatPurchaseRate,
                activeCustomers: ds.activeCustomers, overallScore: score
            };
        }

        /* One composite for the gradebook, the verdict and the debrief: growth over the inherited
           USD 1M month (trailing two quarters), brand equity, blended CAC and the active customer base. */
        _composite(ds) {
            var clamp = this._clamp;
            var rh = ds.revenueHistory || [];
            if (!rh.length) return 0;
            var trail = rh.length > 1 ? (rh[rh.length - 1] + rh[rh.length - 2]) / 2 : rh[rh.length - 1];
            var g = trail / 1000000 - 1;
            var gs = clamp((g + 0.10) / 0.25, 0, 1);
            var bs = clamp((ds.brandEquity - 32) / 20, 0, 1);
            var cs = clamp((38 - ds.cac) / 14, 0, 1);
            var rs = clamp(((ds.activeCustomers || 50000) / 50000 - 0.85) / 0.30, 0, 1);
            return Math.round(clamp(100 * (0.35 * gs + 0.25 * bs + 0.20 * cs + 0.20 * rs), 0, 100));
        }

        _tier(score) {
            if (score >= 72) return 'excellent';
            if (score >= 55) return 'good';
            if (score >= 38) return 'adequate';
            return 'developing';
        }

