        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var dec = history.map(function(h) { return h.decisions || {}; });
            var res = history.map(function(h) { return h.results || {}; });
            var last = res[res.length - 1];
            var n = history.length;
            var mean = function(f) { return dec.reduce(function(s, x) { return s + (Number(x[f]) || 0); }, 0) / n; };
            var score = Math.round(Number(last.overallScore != null ? last.overallScore : 0));
            var tier = this._tier(score);
            var finalRevenue = last.monthlyRevenue || 0;
            var growth = Math.round((finalRevenue / 1000000 - 1) * 100);
            var finalBrand = last.brandEquity || 0;
            var finalCac = last.cac || 0;
            var finalClv = last.clv || 0;
            var avgRoas = res.reduce(function(s, r) { return s + (r.roas || 0); }, 0) / n;

            var insights = [];
            var mistakes = [];
            var semAff = mean('semPct') + mean('affiliatePct');
            if (mean('semPct') >= 40 || semAff >= 55) {
                mistakes.push('trap');
                insights.push(this._fill('ins_trap', { pct: this._num(semAff, 0), r1: this._num(res[0].roas, 2), rn: this._num(last.roas, 2) }));
            }
            var r3 = dec[2] || {}, r4 = dec[3] || {}, r5 = dec[4] || {};
            if (n >= 4 && ((r4.socialPct || 0) >= 35 || (r5.socialPct || 0) >= 35 || ((r3.brandFocus || 0) - Math.min(r4.brandFocus || 0, (n >= 5 ? r5.brandFocus : r4.brandFocus) || 0) >= 20))) {
                mistakes.push('ios');
                insights.push(this._fill('ins_ios', { soc: this._num(Math.max(r4.socialPct || 0, r5.socialPct || 0), 0), b3: this._num(r3.brandFocus || 0, 0), b4: this._num(r4.brandFocus || 0, 0) }));
            }
            if (mean('emailPct') < 6) {
                mistakes.push('care');
                insights.push(this._fill('ins_care', { pct: this._num(mean('emailPct'), 0), rr: this._num(last.repeatRate || 0, 1) }));
            }
            if (mean('brandFocus') >= 75) {
                mistakes.push('brandx');
                insights.push(this._fill('ins_brandx', { bf: this._num(mean('brandFocus'), 0), cac: this._num(finalCac, 2) }));
            } else if (mean('brandFocus') < 25 && mistakes.indexOf('trap') < 0) {
                mistakes.push('brandlow');
                insights.push(this._fill('ins_brandlow', { bf: this._num(mean('brandFocus'), 0), be: this._num(finalBrand, 0) }));
            }
            var exposure = mean('influencerPct') / 100;
            if (n >= 5 && exposure > 0.18) {
                mistakes.push('creators');
                insights.push(this._fill('ins_creators', { pct: this._num(exposure * 100, 0) }));
            }
            if (!mistakes.length) insights.push(window.mySimulation.t('ins_balanced'));
            insights.push(this._fill('ins_kpis', { rev: this._num(finalRevenue, 0), g: (growth >= 0 ? '+' : '') + growth, be: this._num(finalBrand, 0), cac: this._num(finalCac, 2) }));

            var scores = res.map(function(r) { return Number(r.overallScore) || 0; });
            var tpRound = 1, tpDelta = 0;
            for (var i = 1; i < scores.length; i++) {
                var dlt = scores[i] - scores[i - 1];
                if (Math.abs(dlt) > Math.abs(tpDelta)) { tpDelta = dlt; tpRound = i + 1; }
            }
            var td = dec[tpRound - 1] || {};
            var turningPoint = this._fill(tpDelta < 0 ? 'tp_down' : 'tp_up', {
                r: tpRound, a: tpRound > 1 ? scores[tpRound - 2] : scores[0], b: scores[tpRound - 1],
                sem: this._num(td.semPct, 0), soc: this._num(td.socialPct, 0), em: this._num(td.emailPct, 0),
                co: this._num(td.contentPct, 0), inf: this._num(td.influencerPct, 0), af: this._num(td.affiliatePct, 0), bf: this._num(td.brandFocus, 0)
            });

            return {
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: window.mySimulation.t('tier_' + tier),
                overallScore: score,
                totalScore: score,
                score: score,
                composite: score,
                revenueGrowth: growth + '%',
                finalRevenue: finalRevenue,
                finalBrandEquity: finalBrand,
                averageRoas: Math.round(avgRoas * 100) / 100,
                finalCac: finalCac,
                finalClv: finalClv,
                mistakes: mistakes,
                turningPoint: turningPoint,
                questions: [window.mySimulation.t('q1'), window.mySimulation.t('q2'), window.mySimulation.t('q3')],
                insights: insights,
                totalPeriods: n
            };
        }

